//! Cross-language golden tests: assert brix-core reproduces the Python
//! implementation exactly, from fixtures generated by `rust/golden/generate.py`
//! running the real Python code. If Python's fingerprint/pattern/shlex
//! semantics change, regenerate the fixtures and re-run.

use std::collections::BTreeMap;

use std::path::Path;

use brix_core::data::DataAtom;
use brix_core::fingerprint::{digest, Value};
use brix_core::patterns::{overlaps, PathPattern};
use brix_core::shlex;
use brix_core::TimeAndHashChangeDetector;
use serde_json::Value as J;

/// The committed fixture tree (`rust/golden/tree`), relative to this crate.
fn tree_root() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../golden/tree")
}

fn to_value(j: &J) -> Value {
    match j {
        J::Null => Value::Null,
        J::Bool(b) => Value::Bool(*b),
        J::Number(n) => Value::Int(n.as_i64().expect("payloads are int-only, no floats")),
        J::String(s) => Value::Str(s.clone()),
        J::Array(a) => Value::List(a.iter().map(to_value).collect()),
        J::Object(o) => {
            let mut m = BTreeMap::new();
            for (k, v) in o {
                m.insert(k.clone(), to_value(v));
            }
            Value::Map(m)
        }
    }
}

fn load(name: &str) -> J {
    let text = match name {
        "digests" => include_str!("golden/digests.json"),
        "patterns" => include_str!("golden/patterns.json"),
        "overlaps" => include_str!("golden/overlaps.json"),
        "shlex" => include_str!("golden/shlex.json"),
        "plans" => include_str!("golden/plans.json"),
        "keys" => include_str!("golden/keys.json"),
        "regex" => include_str!("golden/regex.json"),
        "fs" => include_str!("golden/fs.json"),
        _ => unreachable!(),
    };
    serde_json::from_str(text).expect("valid golden JSON")
}

#[test]
fn digests_match_python() {
    let cases = load("digests");
    for case in cases.as_array().unwrap() {
        let payload = to_value(&case["payload"]);
        let expected = case["digest"].as_str().unwrap();
        assert_eq!(
            digest(&payload),
            expected,
            "digest mismatch for payload {}",
            case["payload"]
        );
    }
}

fn sorted_bindings(mut v: Vec<(String, String)>) -> Vec<(String, String)> {
    v.sort();
    v
}

#[test]
fn patterns_match_python() {
    let cases = load("patterns");
    for case in cases.as_array().unwrap() {
        let template = case["template"].as_str().unwrap();
        let p = PathPattern::new(template).unwrap();

        assert_eq!(p.is_concrete(), case["is_concrete"].as_bool().unwrap(), "is_concrete {template}");
        assert_eq!(
            p.literal_prefix_dir(),
            case["literal_prefix_dir"].as_str().unwrap(),
            "literal_prefix_dir {template}"
        );

        for m in case["matches"].as_array().unwrap() {
            let path = m["path"].as_str().unwrap();
            let got = p.matches(path);
            match &m["bindings"] {
                J::Null => assert!(got.is_none(), "expected no match: {template} vs {path}, got {got:?}"),
                J::Object(obj) => {
                    let got = got.unwrap_or_else(|| panic!("expected match: {template} vs {path}"));
                    let want: Vec<(String, String)> = obj
                        .iter()
                        .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                        .collect();
                    assert_eq!(
                        sorted_bindings(got),
                        sorted_bindings(want),
                        "bindings {template} vs {path}"
                    );
                }
                other => panic!("bad fixture bindings: {other}"),
            }
        }

        for s in case["substitutions"].as_array().unwrap() {
            let binds: Vec<(String, String)> = s["bindings"]
                .as_object()
                .unwrap()
                .iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect();
            assert_eq!(
                p.substitute(&binds),
                s["result"].as_str().unwrap(),
                "substitute {template} with {:?}",
                s["bindings"]
            );
        }
    }
}

#[test]
fn overlaps_match_python() {
    let cases = load("overlaps");
    for case in cases.as_array().unwrap() {
        let a = PathPattern::new(case["a"].as_str().unwrap()).unwrap();
        let b = PathPattern::new(case["b"].as_str().unwrap()).unwrap();
        assert_eq!(
            overlaps(&a, &b),
            case["overlaps"].as_bool().unwrap(),
            "overlaps {} ~ {}",
            case["a"],
            case["b"]
        );
    }
}

#[test]
fn plans_match_python() {
    let cases = load("plans");
    for case in cases.as_array().unwrap() {
        // The spec is a raw JSON string so key order survives (see generate.py).
        let spec = brix_core::spec::parse(case["spec"].as_str().unwrap()).expect("parse spec");
        let targets: Option<Vec<String>> = match &case["targets"] {
            J::Null => None,
            J::Array(a) => Some(a.iter().map(|v| v.as_str().unwrap().to_string()).collect()),
            other => panic!("bad targets fixture: {other}"),
        };
        let plan = brix_core::plan_graph(spec.actions, "/root", targets.as_deref())
            .expect("plan_graph");
        assert_eq!(
            plan.describe(),
            case["describe"].as_str().unwrap(),
            "describe mismatch: graph {} targets {}",
            case["name"],
            case["targets"]
        );
    }
}

#[test]
fn keys_match_python() {
    for case in load("keys").as_array().unwrap() {
        let action: brix_core::Action =
            serde_json::from_str(case["spec"].as_str().unwrap()).expect("parse action spec");
        let got = match case["kind"].as_str().unwrap() {
            "action_key" => brix_core::action_key(&action),
            "membership_key" => brix_core::membership_key(&action),
            other => panic!("bad key kind {other}"),
        }
        .expect("key");
        assert_eq!(got, case["key"].as_str().unwrap(), "{} mismatch", case["kind"]);
    }
}

#[test]
fn regex_matches_python() {
    let data = load("regex");
    for case in data["match"].as_array().unwrap() {
        let atom = DataAtom::Regex { pattern: case["pattern"].as_str().unwrap().to_string() };
        let got = atom.regex_match(case["path"].as_str().unwrap());
        match &case["bindings"] {
            J::Null => assert!(got.is_none(), "expected no match: {} vs {}", case["pattern"], case["path"]),
            J::Object(obj) => {
                let got = got.unwrap_or_else(|| panic!("expected match: {} vs {}", case["pattern"], case["path"]));
                let want: Vec<(String, String)> = obj
                    .iter()
                    .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                    .collect();
                assert_eq!(sorted_bindings(got), sorted_bindings(want), "{} vs {}", case["pattern"], case["path"]);
            }
            other => panic!("bad regex bindings fixture: {other}"),
        }
    }
    for case in data["substitute"].as_array().unwrap() {
        let atom = DataAtom::Regex { pattern: case["pattern"].as_str().unwrap().to_string() };
        let binds: Vec<(String, String)> = case["bindings"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
            .collect();
        match atom.substitute(&binds) {
            DataAtom::Regex { pattern } => assert_eq!(
                pattern,
                case["result"].as_str().unwrap(),
                "substitute {} with {:?}",
                case["pattern"],
                case["bindings"]
            ),
            other => panic!("substitute changed atom kind: {other:?}"),
        }
    }
}

#[test]
fn fs_matches_python() {
    let tree = tree_root();
    let data = load("fs");

    for case in data["find"].as_array().unwrap() {
        let template = case["template"].as_str().unwrap();
        let got = PathPattern::new(template).unwrap().find(&tree);
        let want = case["results"].as_array().unwrap();
        assert_eq!(got.len(), want.len(), "find count for {template}");
        for (g, w) in got.iter().zip(want) {
            let w = w.as_array().unwrap();
            assert_eq!(g.0, w[0].as_str().unwrap(), "find path for {template}");
            let want_binds: Vec<(String, String)> = w[1]
                .as_object()
                .unwrap()
                .iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect();
            assert_eq!(
                sorted_bindings(g.1.clone()),
                sorted_bindings(want_binds),
                "find bindings for {template} at {}",
                g.0
            );
        }
    }

    let det = TimeAndHashChangeDetector::new();
    for case in data["hash_file"].as_array().unwrap() {
        let path = tree.join(case["path"].as_str().unwrap());
        let got = det.hash_file(&path);
        match &case["hash"] {
            J::Null => assert!(got.is_none(), "expected None hash for {}", case["path"]),
            J::String(s) => assert_eq!(got.as_deref(), Some(s.as_str()), "hash for {}", case["path"]),
            other => panic!("bad hash fixture: {other}"),
        }
    }
}

#[test]
fn shlex_matches_python() {
    let cases = load("shlex");
    for case in cases.as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        let got = shlex::split(input);
        if case.get("error").and_then(|e| e.as_bool()).unwrap_or(false) {
            assert!(got.is_err(), "expected shlex error for {input:?}, got {got:?}");
        } else {
            let want: Vec<String> = case["argv"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap().to_string())
                .collect();
            assert_eq!(got.unwrap(), want, "shlex split {input:?}");
        }
    }
}
